"""Curated semantic concepts for the Qaroshi v2 lexicon.
One English sense per delimiter; English glosses identify the sense intended.
"""
AREAS = []

def add(domain, pos, concepts):
    terms = [s.strip().replace("\n", " ") for s in concepts.split("|")]
    AREAS.append((domain, pos, [x for x in terms if x]))

